package com.dawnrise.school.announcement;
import com.dawnrise.school.school.exception.ResourceNotFoundException;import org.springframework.dao.OptimisticLockingFailureException;import org.springframework.jdbc.core.namedparam.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class DawnriseReleaseService {
 private final NamedParameterJdbcTemplate jdbc;public DawnriseReleaseService(NamedParameterJdbcTemplate jdbc){this.jdbc=jdbc;}
 @Transactional public ReleaseDtos.View create(long actor,ReleaseDtos.Create r){plain(r.title());plain(r.summary());plain(r.details());if(r.scheduledAt()!=null&&!r.scheduledAt().isAfter(OffsetDateTime.now()))throw new IllegalArgumentException("Scheduled time must be in the future");if(r.expiresAt()!=null&&!r.expiresAt().isAfter(r.scheduledAt()==null?OffsetDateTime.now():r.scheduledAt()))throw new IllegalArgumentException("Expiry must follow publication");Set<Long> orgs=resolveOrganizations(r);String status=r.scheduledAt()==null?"DRAFT":"SCHEDULED";Long id=jdbc.queryForObject("INSERT INTO dawnrise_releases(title,summary,details,status,scheduled_at,expires_at,created_by_platform_user_id) VALUES(:title,:summary,:details,:status,:scheduled,:expires,:actor) RETURNING id",new MapSqlParameterSource("title",r.title().trim()).addValue("summary",r.summary().trim()).addValue("details",r.details().trim()).addValue("status",status).addValue("scheduled",r.scheduledAt()).addValue("expires",r.expiresAt()).addValue("actor",actor),Long.class);for(long org:orgs)jdbc.update("INSERT INTO dawnrise_release_organizations(release_id,organization_id) VALUES(:id,:org)",new MapSqlParameterSource("id",id).addValue("org",org));audit(id,actor,"CREATED");if("SCHEDULED".equals(status)){enqueue(id,r.title(),r.summary(),orgs,r.scheduledAt());audit(id,actor,"SCHEDULED");}return get(id);}
 @Transactional(readOnly=true) public ReleaseDtos.View get(long id){var rows=jdbc.query("SELECT * FROM dawnrise_releases WHERE id=:id",new MapSqlParameterSource("id",id),(rs,n)->new ReleaseDtos.View(id,rs.getString("title"),rs.getString("summary"),rs.getString("details"),rs.getString("status"),Set.copyOf(jdbc.queryForList("SELECT organization_id FROM dawnrise_release_organizations WHERE release_id=:id ORDER BY organization_id",new MapSqlParameterSource("id",id),Long.class)),rs.getObject("scheduled_at",OffsetDateTime.class),rs.getObject("published_at",OffsetDateTime.class),rs.getObject("expires_at",OffsetDateTime.class),rs.getLong("version")));if(rows.isEmpty())throw new ResourceNotFoundException("Release not found");return rows.getFirst();}
 @Transactional(readOnly=true) public ReleaseDtos.View getForOrganization(long organizationId,long id){Long found=jdbc.query("SELECT r.id FROM dawnrise_releases r JOIN dawnrise_release_organizations o ON o.release_id=r.id WHERE r.id=:id AND o.organization_id=:org AND r.status IN ('PUBLISHED','EXPIRED')",new MapSqlParameterSource("id",id).addValue("org",organizationId),(rs,n)->rs.getLong(1)).stream().findFirst().orElseThrow(()->new ResourceNotFoundException("Release not found"));return get(found);}
 @Transactional public ReleaseDtos.View publish(long actor,long id,long version){var r=get(id);if(!List.of("DRAFT","SCHEDULED").contains(r.status()))throw new IllegalStateException("Release cannot be published");if(jdbc.update("UPDATE dawnrise_releases SET status='PUBLISHED',published_at=CURRENT_TIMESTAMP,scheduled_at=NULL,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND version=:version",new MapSqlParameterSource("id",id).addValue("version",version))!=1)throw new OptimisticLockingFailureException("Release changed");jdbc.update("UPDATE school_notification_outbox SET status='CANCELLED',updated_at=CURRENT_TIMESTAMP WHERE source_type='RELEASE' AND source_id=:id AND status='PENDING'",new MapSqlParameterSource("id",id));enqueue(id,r.title(),r.summary(),r.organizationIds(),OffsetDateTime.now());audit(id,actor,"PUBLISHED");return get(id);}
 @Transactional public ReleaseDtos.View cancel(long actor,long id,long version){var r=get(id);if(List.of("CANCELLED","EXPIRED").contains(r.status()))throw new IllegalStateException("Release cannot be cancelled");if(jdbc.update("UPDATE dawnrise_releases SET status='CANCELLED',cancelled_at=CURRENT_TIMESTAMP,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND version=:version",new MapSqlParameterSource("id",id).addValue("version",version))!=1)throw new OptimisticLockingFailureException("Release changed");jdbc.update("UPDATE school_notification_outbox SET status='CANCELLED',updated_at=CURRENT_TIMESTAMP WHERE source_type='RELEASE' AND source_id=:id AND status='PENDING'",new MapSqlParameterSource("id",id));audit(id,actor,"CANCELLED");return get(id);}
 @Transactional public void advance(){jdbc.update("INSERT INTO dawnrise_release_audit(release_id,actor_platform_user_id,action) SELECT id,created_by_platform_user_id,'PUBLISHED' FROM dawnrise_releases WHERE status='SCHEDULED' AND scheduled_at<=CURRENT_TIMESTAMP",Map.of());jdbc.update("UPDATE dawnrise_releases SET status='PUBLISHED',published_at=CURRENT_TIMESTAMP,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE status='SCHEDULED' AND scheduled_at<=CURRENT_TIMESTAMP",Map.of());jdbc.update("INSERT INTO dawnrise_release_audit(release_id,actor_platform_user_id,action) SELECT id,created_by_platform_user_id,'EXPIRED' FROM dawnrise_releases WHERE status='PUBLISHED' AND expires_at<=CURRENT_TIMESTAMP",Map.of());jdbc.update("UPDATE dawnrise_releases SET status='EXPIRED',version=version+1,updated_at=CURRENT_TIMESTAMP WHERE status='PUBLISHED' AND expires_at<=CURRENT_TIMESTAMP",Map.of());jdbc.update("UPDATE school_notification_outbox o SET status='CANCELLED',updated_at=CURRENT_TIMESTAMP FROM dawnrise_releases r WHERE o.source_type='RELEASE' AND o.source_id=r.id AND r.status IN ('EXPIRED','CANCELLED') AND o.status='PENDING'",Map.of());}
 private Set<Long> resolveOrganizations(ReleaseDtos.Create r){if(r.allActiveOrganizations()&&r.organizationIds()!=null&&!r.organizationIds().isEmpty())throw new IllegalArgumentException("Choose all organizations or selected organizations");Set<Long> requested=r.allActiveOrganizations()?Set.copyOf(jdbc.queryForList("SELECT id FROM schools WHERE status='ACTIVE'",Map.of(),Long.class)):r.organizationIds()==null?Set.of():Set.copyOf(r.organizationIds());if(requested.isEmpty())throw new IllegalArgumentException("At least one active organization is required");Set<Long> active=Set.copyOf(jdbc.queryForList("SELECT id FROM schools WHERE status='ACTIVE' AND id IN (:ids)",new MapSqlParameterSource("ids",requested),Long.class));if(!active.equals(requested))throw new IllegalArgumentException("An organization is not active");return active;}
 private void enqueue(long id,String title,String summary,Set<Long> orgs,OffsetDateTime at){for(long org:orgs)jdbc.update("INSERT INTO school_notification_outbox(source_type,source_id,organization_id,source_event_id,event_type,importance,heading,context,audience_spec,available_at) VALUES('RELEASE',:id,:org,:source,'DAWNRISE_RELEASE','NORMAL',:title,:summary,'[{\"type\":\"WHOLE_SCHOOL\",\"key\":null}]'::jsonb,:at) ON CONFLICT(source_type,source_id,organization_id) DO UPDATE SET status='PENDING',available_at=EXCLUDED.available_at,updated_at=CURRENT_TIMESTAMP",new MapSqlParameterSource("id",id).addValue("org",org).addValue("source","release:"+id+":"+org).addValue("title",title).addValue("summary",summary).addValue("at",at));}
 private void audit(long id,long actor,String action){jdbc.update("INSERT INTO dawnrise_release_audit(release_id,actor_platform_user_id,action) VALUES(:id,:actor,:action)",new MapSqlParameterSource("id",id).addValue("actor",actor).addValue("action",action));}private void plain(String s){if(s.contains("<")||s.contains(">"))throw new IllegalArgumentException("Release text must be plain text");}
}
